CREATE TYPE "role" AS ENUM ('SUPER_ADMIN','ADMIN','USER','VIEWER');
CREATE TYPE "server_state" AS ENUM ('PENDING','SCHEDULING','INSTALLING','STARTING','RUNNING','STOPPING','STOPPED','BACKING_UP','RESTORING','MIGRATING','FAILED');
CREATE TYPE "desired_server_state" AS ENUM ('RUNNING','STOPPED');
CREATE TYPE "task_status" AS ENUM ('QUEUED','RUNNING','SUCCESS','FAILED','CANCELLED');
CREATE TYPE "task_type" AS ENUM ('CREATE_SERVER','START_SERVER','STOP_SERVER','RESTART_SERVER','BACKUP_SERVER','RESTORE_SERVER','MIGRATE_SERVER','REINSTALL_SERVER','DELETE_SERVER','RECONCILE_SERVER');
CREATE TABLE "organizations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"name" text NOT NULL,"slug" text NOT NULL UNIQUE,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "projects" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" uuid NOT NULL REFERENCES "organizations"("id"),"name" text NOT NULL,"slug" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "projects_org_slug_uq" ON "projects" ("organization_id","slug");
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" uuid NOT NULL REFERENCES "organizations"("id"),"email" text NOT NULL UNIQUE,"name" text NOT NULL,"password_hash" text NOT NULL,"role" role NOT NULL DEFAULT 'USER',"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"token_hash" text NOT NULL UNIQUE,"expires_at" timestamptz NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),"last_seen_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "nodes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"kubernetes_uid" text NOT NULL UNIQUE,"name" text NOT NULL UNIQUE,"healthy" boolean NOT NULL DEFAULT false,"maintenance" boolean NOT NULL DEFAULT false,"scheduling_enabled" boolean NOT NULL DEFAULT true,"cpu_millicores" integer NOT NULL DEFAULT 0,"memory_mib" integer NOT NULL DEFAULT 0,"storage_gib" integer NOT NULL DEFAULT 0,"allocated_cpu_millicores" integer NOT NULL DEFAULT 0,"allocated_memory_mib" integer NOT NULL DEFAULT 0,"allocated_storage_gib" integer NOT NULL DEFAULT 0,"labels" jsonb NOT NULL DEFAULT '{}',"taints" jsonb NOT NULL DEFAULT '[]',"kubernetes_version" text,"internal_ip" text,"last_seen_at" timestamptz NOT NULL DEFAULT now(),"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "servers" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"project_id" uuid NOT NULL REFERENCES "projects"("id"),"name" text NOT NULL,"adapter_id" text NOT NULL,"configuration" jsonb NOT NULL,"desired_state" desired_server_state NOT NULL DEFAULT 'RUNNING',"actual_state" server_state NOT NULL DEFAULT 'PENDING',"node_id" uuid REFERENCES "nodes"("id"),"cpu_millicores" integer NOT NULL,"memory_mib" integer NOT NULL,"storage_gib" integer NOT NULL,"kubernetes_name" text NOT NULL UNIQUE,"last_error_code" text,"last_error_message" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "servers_project_name_uq" ON "servers" ("project_id","name");
CREATE INDEX "servers_state_idx" ON "servers" ("desired_state","actual_state");
CREATE TABLE "tasks" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"project_id" uuid NOT NULL REFERENCES "projects"("id"),"server_id" uuid REFERENCES "servers"("id") ON DELETE CASCADE,"type" task_type NOT NULL,"status" task_status NOT NULL DEFAULT 'QUEUED',"progress" integer NOT NULL DEFAULT 0,"current_step" text,"idempotency_key" text NOT NULL UNIQUE,"error_code" text,"error_message" text,"metadata" jsonb NOT NULL DEFAULT '{}',"created_at" timestamptz NOT NULL DEFAULT now(),"started_at" timestamptz,"finished_at" timestamptz);
CREATE UNIQUE INDEX "tasks_one_active_server_uq" ON "tasks" ("server_id") WHERE "status" in ('QUEUED', 'RUNNING');
CREATE TABLE "scheduling_decisions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"server_id" uuid NOT NULL REFERENCES "servers"("id") ON DELETE CASCADE,"selected_node_id" uuid REFERENCES "nodes"("id"),"explanation" text NOT NULL,"candidates" jsonb NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "port_allocations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"server_id" uuid NOT NULL REFERENCES "servers"("id") ON DELETE CASCADE,"node_id" uuid NOT NULL REFERENCES "nodes"("id"),"port" integer NOT NULL,"protocol" text NOT NULL,"purpose" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "ports_protocol_port_uq" ON "port_allocations" ("protocol","port");
CREATE UNIQUE INDEX "ports_server_purpose_protocol_uq" ON "port_allocations" ("server_id","purpose","protocol");
CREATE TABLE "activity_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" uuid NOT NULL REFERENCES "organizations"("id"),"project_id" uuid REFERENCES "projects"("id"),"actor_id" uuid REFERENCES "users"("id"),"server_id" uuid REFERENCES "servers"("id") ON DELETE SET NULL,"type" text NOT NULL,"message" text NOT NULL,"metadata" jsonb NOT NULL DEFAULT '{}',"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "console_lines" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"server_id" uuid NOT NULL REFERENCES "servers"("id") ON DELETE CASCADE,"stream" text NOT NULL,"line" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
